INSERT INTO `roles` (`id`,`name`,`description`,`is_admin`,`is_system`,`all_sites`,`created_at`,`updated_at`) VALUES
(1,'Company Administrator','Everything in every module, including user accounts, roles, page access, construction and company settings, and the closing date.',1,1,1,'2026-10-23 20:35:44',NULL),
(2,'Business Owner / President','Sees every project, report and transaction and gives the final executive approvals. (The Company Owner account has full authority in any case.)',0,1,1,'2026-10-23 20:35:44',NULL),
(3,'General Manager','Runs the company day to day: every project, contract and report, and the authorized-approver step of contracts, billings, change orders and large purchases.',0,1,1,'2026-10-23 20:35:44',NULL),
(4,'Operations Manager','All field operations across projects: site reports, workforce, equipment, procurement and subcontracts, with approval rights on them.',0,1,1,'2026-10-23 20:35:44',NULL),
(5,'Project Director','Directs a portfolio of projects: contracts, budgets, schedules and change orders, and the director-level approvals.',0,1,1,'2026-10-23 20:35:44',NULL),
(6,'Project Manager','Runs the projects assigned to them: budgets, schedule, materials, workforce, equipment, subcontracts and progress billings, and approves their project\'s documents.',0,1,1,'2026-10-23 20:35:44',NULL),
(7,'Site Engineer','Daily site reports and accomplishments, inspections, RFIs, material requests and issues, timesheets and equipment logs of their projects; prepares the progress billing.',0,1,1,'2026-10-23 20:35:44',NULL),
(8,'Quantity Surveyor','Estimates, BOQ and schedule of values, budgets, change orders, and the measurement of progress and subcontractor billings.',0,1,1,'2026-10-23 20:35:44',NULL),
(9,'Site Supervisor / Foreman','Crew attendance, daily site reports, material requests and equipment logs on site.',0,1,1,'2026-10-23 20:35:44',NULL),
(10,'Human Resources Officer','Worker records, trades and rates, cash advances, and the man-hour and labor cost reports.',0,1,1,'2026-10-23 20:35:44',NULL),
(11,'Timekeeper','Records daily time in and time out of the workers.',0,1,1,'2026-10-23 20:35:44',NULL),
(12,'Equipment Manager','The equipment register, dispatch and booking, usage logs and charges, preventive maintenance and repairs.',0,1,1,'2026-10-23 20:35:44',NULL),
(13,'Warehouse Officer','Receiving and inspection of deliveries, stock, issues, returns and transfers of materials to and between projects.',0,1,1,'2026-10-23 20:35:44',NULL),
(14,'Procurement Officer','Canvass and supplier quotations, purchase orders, supplier and subcontractor records.',0,1,1,'2026-10-23 20:35:44',NULL),
(15,'Purchasing Manager','Approves material requests and purchases, awards canvasses, and manages suppliers and subcontract agreements.',0,1,1,'2026-10-23 20:35:44',NULL),
(16,'Accounting Staff','Day-to-day bookkeeping: bills, checks, receipts, deposits, journal entries, cost code assignment and payroll postings.',0,1,1,'2026-10-23 20:35:44',NULL),
(17,'Chief Accountant / Controller','The books: chart of accounts, period closing, revenue recognition, cost allocation, payroll posting, BIR reports and every financial and project report.',0,1,1,'2026-10-23 20:35:44',NULL),
(18,'Finance Manager','Cash, collections, payments and project finances: approves billings, payments, budgets and allocations, and watches receivables, payables and cash flow.',0,1,1,'2026-10-23 20:35:44',NULL),
(19,'Billing Officer','Progress billing applications, invoices and statements of account, retention and billing reports.',0,1,1,'2026-10-23 20:35:44',NULL),
(20,'Collection Officer / Cashier','Receives client payments and issues official receipts, makes deposits, and works the yard sales counter.',0,1,1,'2026-10-23 20:35:44',NULL),
(21,'Safety Officer','Safety records: incidents, near misses, toolbox meetings, training, PPE, permits to work and hazard assessments; equipment safety inspections.',0,1,1,'2026-10-23 20:35:44',NULL),
(22,'Quality Inspector','Inspection and test plans, quality checklists, material tests, nonconformance reports and corrective actions.',0,1,1,'2026-10-23 20:35:44',NULL),
(23,'Internal Auditor','View-only access to every record, report and the audit trail. Cannot create, change or approve anything.',0,1,1,'2026-10-23 20:35:44',NULL),
(24,'External Client / Client Representative','Portal: the progress, milestones, billings, statements and documents of the client\'s own projects.',0,1,1,'2026-10-23 20:35:44',NULL),
(25,'Subcontractor Portal User','Portal: the subcontractor\'s own agreements, progress claims, retention and payments.',0,1,1,'2026-10-23 20:35:44',NULL);
